package main

import (
	"bytes"
	"log/slog"
	"strings"
	"testing"
)

// TestAutoNextCountdownEnv covers the watch-flow-polish auto-next countdown
// env knob — the autoNextCountdownSeconds resolver wired into
// api.Deps.WatchDefaults (served verbatim by GET /api/v1/watch-defaults).
// unset/empty → the default 10; a set integral value → verbatim; a malformed
// value → the default 10 with envInt's warning; zero or negative → the floor 1
// (a non-positive knob must never make auto-next an instant jump). Empty reads
// as unset because envInt collapses the two — os.Getenv cannot distinguish
// them (the TestEnvInt precedent).
func TestAutoNextCountdownEnv(t *testing.T) {
	const key = "MELLIFERA_AUTO_NEXT_COUNTDOWN_SECONDS"
	for _, tc := range []struct {
		name     string
		val      string
		want     int
		wantWarn bool
	}{
		{"unset_uses_default", "", 10, false},
		{"set_serves_verbatim", "25", 25, false},
		{"one_serves_verbatim_at_floor_boundary", "1", 1, false},
		{"malformed_falls_back_with_warning", "soon", 10, true},
		{"zero_floors_to_one", "0", 1, false},
		{"negative_floors_to_one", "-3", 1, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Setenv(key, tc.val)
			var buf bytes.Buffer
			if tc.wantWarn {
				prev := slog.Default()
				slog.SetDefault(slog.New(slog.NewTextHandler(&buf, nil)))
				t.Cleanup(func() { slog.SetDefault(prev) })
			}
			if got := autoNextCountdownSeconds(); got != tc.want {
				t.Errorf("autoNextCountdownSeconds() with %s=%q = %d, want %d", key, tc.val, got, tc.want)
			}
			if tc.wantWarn && !strings.Contains(buf.String(), key) {
				t.Errorf("malformed %s logged no warning naming the knob; output: %q", key, buf.String())
			}
		})
	}
}
